}

impl Drop for Application {
    fn drop(&mut self) {
        if let Some(request) = &self.active_request {
            request.abort();
        }
    }
}

#[doc = "# Errors\nReturns an error if the provider client cannot be initialized."]
pub fn build(settings: ApplicationSettings) -> Result<(Application, Events), ApplicationError> {
    let mut session = Session::build(settings.provider, settings.session_number)?;
    if matches!(settings.mode, Mode::OpenaiLogin) {
        session.messages.clear();
    }
    let (event_sender, background_events) = mpsc::unbounded_channel();
    let application = Application {
        session,
        statistics: Statistics::default(),
        error: None,
        event_sender,
        active_request: None,
        response_started: None,
        pending_tool_calls: std::collections::VecDeque::new(),
        home_directory: settings.home_directory,
        clipboard_command: settings.clipboard_command,
        mode: settings.mode,
        pending_authorization: None,
        input: interface::Input::default(),
        scroll_from_bottom: usize::MAX,
        maximum_scroll: 0,
        selection: None,
        screen_area: ratatui::layout::Rect::default(),
    };
    Ok((application, background_events))
}

#[doc = "# Errors\nReturns an error if the application cannot run."]
pub async fn run<BackendType, EventSource>(
    settings: ApplicationSettings,
    create_terminal_resources: impl FnOnce() -> (BackendType, EventSource, TerminalMode),
) -> Result<(), ApplicationError>
where
    BackendType: Backend,
    BackendType::Error: Send + Sync + 'static,
    EventSource: Stream<Item = io::Result<Event>> + Unpin,
{
    let (mut application, mut background_events) = build(settings)?;
    match &application.mode {
        Mode::SinglePrompt(prompt) => {
            let prompt = prompt.clone();
            run_single_prompt(&mut application, &mut background_events, prompt).await
        }
        Mode::Interactive | Mode::OpenaiLogin => {
            run_interactive(
                &mut application,
                &mut background_events,
                create_terminal_resources,
            )
            .await
        }
    }
}

async fn run_single_prompt(
    application: &mut Application,
    background_events: &mut Events,
    prompt: String,
) -> Result<(), ApplicationError> {
    chats::send_message(application, prompt);
    let result = events::run_single_prompt_loop(application, background_events).await;
    if let Some(request) = application.active_request.take() {
        request.abort();
    }
    let response = result?;
    let mut output = io::stdout().lock();
    output
        .write_all(response.as_bytes())
        .map_err(|error| ApplicationError::Output(format!("Failed to write response: {error}")))?;
    if !response.ends_with('\n') {
        writeln!(output).map_err(|error| {
            ApplicationError::Output(format!("Failed to write response: {error}"))
        })?;
    }
    Ok(())
}

async fn run_interactive<BackendType, EventSource>(
    application: &mut Application,
    background_events: &mut Events,
    create_terminal_resources: impl FnOnce() -> (BackendType, EventSource, TerminalMode),
) -> Result<(), ApplicationError>
where
    BackendType: Backend,
    BackendType::Error: Send + Sync + 'static,
    EventSource: Stream<Item = io::Result<Event>> + Unpin,
{
    let (backend, events, terminal_mode) = create_terminal_resources();
    let mut interface = build_interface(backend, events, terminal_mode)?;
    let result = async {
        if matches!(application.mode, Mode::OpenaiLogin) {
            let (sender, input) = mpsc::unbounded_channel();
            application.pending_authorization = Some(sender);
            let home_directory = application.home_directory.clone();
            let clipboard_command = application.clipboard_command.clone();
            let event_sender = application.event_sender.clone();
            let connection = application.session.provider.connection.clone();
            let authentication_address = application
                .session
                .provider
                .get_openai_authentication_address()
                .expect("OpenAI login selects the OpenAI provider")
                .to_owned();
            application.active_request = Some(tokio::spawn(async move {
                let result = providers::openai::perform_login(
                    &home_directory,
                    input,
                    &event_sender,
                    &connection,
                    &authentication_address,
                    clipboard_command.as_deref(),
                )
                .await;
                let event = match result {
                    Ok(()) => events::Event::LoginSucceeded,
                    Err(error) => events::Event::LoginFailed(error),
                };
                let _ = event_sender.send(event);
            }));
        }
        events::run_interactive_loop(application, &mut interface, background_events).await
    }
    .await;
    if let Some(request) = application.active_request.take() {
        request.abort();
    }
    let restoration = interface::restore_terminal(&mut interface);
    result.and(restoration)
}

mod storage;

use crate::{
    application::ApplicationError,
    chats::{Message, build_chat},
    models::Model,
    providers::{self, Provider, ProviderSettings},
};

const CONTEXT_NAMES: [&str; 4] = ["read", "edit", "review", "blank"];

pub(crate) struct Session {
    pub provider: Provider,
    pub messages: Vec<Message>,
    pub turn: u64,
    pub turn_start: usize,
    selected_model_position: usize,
    context_position: usize,
    home_directory: std::path::PathBuf,
    storage_path: std::path::PathBuf,
    saved: bool,
}

impl Session {
    pub(crate) fn build(
        settings: ProviderSettings,
        session_number: Option<usize>,
    ) -> Result<Self, ApplicationError> {
        let selected_model_position = Self::select_model_position(&settings)?;
        let home_directory = settings.home_directory.clone();
        let provider = providers::build(settings)?;
        let directory = storage::get_directory(&home_directory).map_err(|error| {
            ApplicationError::Configuration(format!("Failed to locate sessions: {error}"))
        })?;
        let session_path = if let Some(number) = session_number {
            storage::select_session(&directory, number).map_err(|error| {
                ApplicationError::Configuration(format!("Failed to select session: {error}"))
            })?
        } else {
            directory.join(format!("{}.jsonl", uuid::Uuid::new_v4()))
        };
        for context in CONTEXT_NAMES.iter().filter(|context| **context != "blank") {
            let path = home_directory.join(".shodan").join(format!("{context}.md"));
            let _ = std::fs::OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(path);
        }
        let mut session = Self {
            provider,
            messages: Vec::new(),
            turn: 0,
            turn_start: 0,
            selected_model_position,
            context_position: 0,
            home_directory,
            storage_path: session_path,
            saved: session_number.is_some(),
        };
        if session_number.is_some() {
            let snapshot = storage::read_session(&session.storage_path).map_err(|error| {
                ApplicationError::Configuration(format!(
                    "Failed to read session {}: {error}",
                    session.storage_path.display()
                ))
            })?;
            session.context_position = CONTEXT_NAMES
                .iter()
                .position(|context| *context == snapshot.context)
                .ok_or_else(|| {
                    ApplicationError::Configuration(format!(
                        "Unknown session context: {}",
                        snapshot.context
                    ))
                })?;
            if session.provider.get_name() != snapshot.provider {
                return Err(ApplicationError::Configuration(format!(
                    "Session requires provider {}",
                    snapshot.provider
                )));
            }
            session.selected_model_position = session
                .provider
                .models
                .iter()
                .position(|model| model.name == snapshot.model)
                .ok_or_else(|| {
                    ApplicationError::Configuration(format!(
                        "Session model is not configured: {}",
                        snapshot.model
                    ))
                })?;
            session.messages = snapshot.messages;
        } else {
            session.clear_messages();
        }
        Ok(session)
    }

    pub(crate) fn save(&mut self, create: bool) -> Result<(), ApplicationError> {
        if !self.saved && !create {
            return Ok(());
        }
        let snapshot = storage::SessionSnapshot {
            context: self.get_context_name().to_owned(),
            model: self.get_selected_model().name.clone(),
            provider: self.provider.get_name().to_owned(),
            messages: self.messages.clone(),
        };
        storage::write_session(&self.storage_path, &snapshot).map_err(|error| {
            ApplicationError::Output(format!(
                "Failed to save session {}: {error}",
                self.storage_path.display()
            ))
        })?;
        self.saved = true;
        Ok(())
    }

    pub(crate) fn get_saved_selection(
        home_directory: &std::path::Path,
        number: usize,
    ) -> Result<(String, String), ApplicationError> {
        let directory = storage::get_directory(home_directory).map_err(|error| {
            ApplicationError::Configuration(format!("Failed to locate sessions: {error}"))
        })?;
        let path = storage::select_session(&directory, number).map_err(|error| {
            ApplicationError::Configuration(format!("Failed to select session: {error}"))
        })?;
        let snapshot = storage::read_session(&path).map_err(|error| {
            ApplicationError::Configuration(format!(
                "Failed to read session {}: {error}",
                path.display()
            ))
        })?;
        Ok((snapshot.provider, snapshot.model))
    }

    pub(crate) fn select_model_position(
        settings: &ProviderSettings,
    ) -> Result<usize, ApplicationError> {
        let model = settings
            .model_override
            .as_deref()
            .unwrap_or(&settings.default_model);
        settings
            .models
            .iter()
            .position(|configured_model| configured_model.name == model)
            .ok_or_else(|| {
                let provider = settings.selection.get_name();
                ApplicationError::Configuration(format!(
                    "Invalid provider or model selection: model not configured for {provider}: {model}"
                ))
            })
    }

    pub(crate) fn clear_messages(&mut self) {
        self.messages = build_chat(self.get_prompt());
        self.turn_start = 0;
    }

    pub(crate) fn get_context_name(&self) -> &'static str {
        CONTEXT_NAMES[self.context_position]
    }

    fn get_prompt(&self) -> String {
        let context = self.get_context_name();
        if context == "blank" {
            return String::new();
        }
        let context_path = self
            .home_directory
            .join(".shodan")
            .join(format!("{context}.md"));
        let context_prompt = std::fs::read_to_string(context_path).unwrap_or_default();
        let project_prompt = std::fs::read_to_string("AGENTS.md").unwrap_or_default();
        [context_prompt, project_prompt]
            .into_iter()
            .filter(|part| !part.is_empty())
            .collect::<Vec<_>>()
            .join("\n")
    }

    pub(crate) fn cycle_context(&mut self, new_session: bool) {
        self.context_position = (self.context_position + 1) % CONTEXT_NAMES.len();
        if !new_session {
            let prompt = self.get_prompt();
            if let Some(message) = self.messages.first_mut() {
                *message = Message::System(prompt);
            }
            return;
        }
        let last_response = self
            .messages
            .iter()
            .rev()
            .find_map(|message| match message {
                Message::Model {
                    content,
                    aborted: false,
                    tool_calls,
                    ..
                } if tool_calls.is_empty() && !content.is_empty() => Some(content.clone()),
                _ => None,
            });
        self.storage_path = self
            .storage_path
            .with_file_name(format!("{}.jsonl", uuid::Uuid::new_v4()));
        self.saved = false;
        self.clear_messages();
        if let Some(content) = last_response {
            self.messages.push(Message::Model {
                content,
                thinking: String::new(),
                tool_calls: Vec::new(),
                provider_items: Vec::new(),
                aborted: false,
            });
        }
    }

    pub(crate) fn get_selected_model(&self) -> &Model {
        &self.provider.models[self.selected_model_position]
    }

    pub(crate) fn cycle_model(&mut self) {
        self.selected_model_position =
            (self.selected_model_position + 1) % self.provider.models.len();
    }
}

use std::collections::VecDeque;

use tokio::time::Instant;

use crate::{application::Application, events::Event, providers, tools};

#[derive(Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct ToolCall {
    pub(crate) id: String,
    pub(crate) name: String,
    pub(crate) arguments: String,
}

#[derive(Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub(crate) enum Message {
    System(String),
    User(String),
    Model {
        content: String,
        thinking: String,
        tool_calls: Vec<ToolCall>,
        provider_items: Vec<serde_json::Value>,
        aborted: bool,
    },
    ToolResult {
        call_id: String,
        content: String,
        display: Option<tools::ToolDisplay>,
    },
    FailedResponse(String),
}

pub(crate) fn build_chat(prompt: String) -> Vec<Message> {
    vec![Message::System(prompt)]
}

fn append_model_message(application: &mut Application) {
    application.session.messages.push(Message::Model {
        content: String::new(),
        thinking: String::new(),
        tool_calls: Vec::new(),
        provider_items: Vec::new(),
        aborted: false,
    });
}

pub(crate) fn send_message(application: &mut Application, content: String) {
    application.session.turn = application.session.turn.wrapping_add(1);
    application.session.messages.push(Message::User(content));
    application.error = None;
    if let Err(error) = application.session.save(true) {
        application.error = Some(error);
        return;
    }
    application.session.turn_start = application.session.messages.len();
    let messages = application.session.messages.clone();
    append_model_message(application);
    application.response_started = Some(Instant::now());
    start_response(application, messages);
}

fn take_partial_response(application: &mut Application) -> (String, String) {
    let mut partial_thinking = String::new();
    let mut partial_response = String::new();
    for message in application
        .session
        .messages
        .drain(application.session.turn_start..)
    {
        if let Message::Model {
            thinking, content, ..
        } = message
        {
            if !thinking.is_empty() {
                partial_thinking.push_str(&thinking);
                partial_thinking.push('\n');
            }
            partial_response.push_str(&content);
        }
    }
    (partial_thinking, partial_response)
}

fn mark_response_aborted(application: &mut Application) {
    let (partial_thinking, partial_response) = take_partial_response(application);
    application.session.messages.push(Message::Model {
        content: partial_response,
        thinking: partial_thinking.trim_end_matches('\n').to_owned(),
        tool_calls: Vec::new(),
        provider_items: Vec::new(),
        aborted: true,
    });
}

fn start_response(application: &mut Application, messages: Vec<Message>) {
    let mut provider = application.session.provider.clone();
    provider.connection.read_context = application.session.get_context_name() == "read";
    let selected_model = application.session.get_selected_model();
    let model = selected_model.name.clone();
    let thinking_level = selected_model.thinking_level;
    let event_sender = application.event_sender.clone();
    let turn = application.session.turn;
    application.active_request = Some(tokio::spawn(async move {
        providers::stream_response(
            &provider,
            &model,
            thinking_level,
            &messages,
            turn,
            &event_sender,
        )
        .await;
    }));
}

pub(crate) fn abort_response(application: &mut Application) {
    let Some(request) = application.active_request.take() else {
        return;
    };
    request.abort();
    application.session.turn = application.session.turn.wrapping_add(1);
    application.pending_tool_calls.clear();
    application.response_started = None;
    mark_response_aborted(application);
    if let Err(error) = application.session.save(false) {
        application.error = Some(error);
    }
}

fn start_next_tool(application: &mut Application) {
    let Some(call) = application.pending_tool_calls.pop_front() else {
        let messages = application.session.messages.clone();
        append_model_message(application);
        start_response(application, messages);
        return;
    };
    let turn = application.session.turn;
    let event_sender = application.event_sender.clone();
    let allowed = application.session.get_context_name() != "read" || call.name != "edit";
    application.active_request = Some(tokio::spawn(async move {
        let (content, display) = if allowed {
            tools::execute(&call.name, &call.arguments).await
        } else {
            ("Error: tool unavailable in read context".to_owned(), None)
        };
        let _ = event_sender.send(Event::ToolCompleted {
            turn,
            call_id: call.id,
            content,
            display,
        });
    }));
}

fn finish_login(application: &mut Application) {
    application.active_request = None;
    application.pending_authorization = None;
    application.session.clear_messages();
    application.input.clear();
    application.scroll_from_bottom = 0;
    application.selection = None;
    application.mode = crate::settings::Mode::Interactive;
}

fn save_provider_items(application: &mut Application, items: Vec<serde_json::Value>) {
    if let Some(Message::Model { provider_items, .. }) = application.session.messages.last_mut() {
        *provider_items = items;
    }
}

fn save_session(application: &mut Application) {
    if let Err(error) = application.session.save(false) {
        application.error = Some(error);
    }
}

fn handle_failed_request(
    application: &mut Application,
    error: crate::application::ApplicationError,
) {
    application.active_request = None;
    application.error = Some(error);
    application.response_started = None;
    let (partial_thinking, partial_response) = take_partial_response(application);
    application
        .session
        .messages
        .push(Message::FailedResponse(format!(
            "{partial_thinking}{partial_response}"
        )));
    save_session(application);
}

pub(crate) fn apply_event(application: &mut Application, event: Event) {
    match event {
        Event::LoginMessage(message) => application
            .session
            .messages
            .push(Message::FailedResponse(message)),
        Event::LoginSucceeded => finish_login(application),
        Event::LoginFailed(error) => {
            application.active_request = None;
            application.pending_authorization = None;
            application
                .session
                .messages
                .push(Message::FailedResponse(error));
        }
        Event::MessageDelta { turn, content }
            if turn == application.session.turn && application.response_started.is_some() =>
        {
            let Some(Message::Model {
                content: message, ..
            }) = application.session.messages.last_mut()
            else {
                return;
            };
            message.push_str(&content);
        }
        Event::ThinkingDelta { turn, content }
            if turn == application.session.turn && application.response_started.is_some() =>
        {
            let Some(Message::Model { thinking, .. }) = application.session.messages.last_mut()
            else {
                return;
            };
            thinking.push_str(&content);
        }
        Event::ToolCallReceived { turn, call }
            if turn == application.session.turn && application.response_started.is_some() =>
        {
            let Some(Message::Model { tool_calls, .. }) = application.session.messages.last_mut()
            else {
                return;
            };
            tool_calls.push(call);
        }
        Event::ProviderItemsReceived { turn, items }
            if turn == application.session.turn && application.response_started.is_some() =>
        {
            save_provider_items(application, items);
        }
        Event::ResponseEnded {
            turn,
            prompt_tokens,
            completion_tokens,
            cached_tokens,
        } if turn == application.session.turn && application.response_started.is_some() => {
            application.active_request = None;
            application.statistics.prompt_tokens += prompt_tokens;
            application.statistics.cached_tokens += cached_tokens;
            application.statistics.completion_tokens += completion_tokens;
            save_session(application);
            let Some(Message::Model { tool_calls, .. }) = application.session.messages.last()
            else {
                return;
            };
            if tool_calls.is_empty() {
                application.statistics.response_time = application
                    .response_started
                    .take()
                    .map(|started| started.elapsed());
            } else {
                application.pending_tool_calls = VecDeque::from(tool_calls.clone());
                start_next_tool(application);
            }
        }
        Event::ToolCompleted {
            turn,
            call_id,
            content,
            display,
        } if turn == application.session.turn && application.response_started.is_some() => {
            application.active_request = None;
            application.session.messages.push(Message::ToolResult {
                call_id,
                content,
                display,
            });
            save_session(application);
            start_next_tool(application);
        }
        Event::RequestFailed { turn, error }
            if turn == application.session.turn && application.response_started.is_some() =>
        {
            handle_failed_request(application, error);
        }
        _ => {}
    }
}

use std::{io, time::Duration};

use crossterm::event::Event as TerminalEvent;
use futures_util::Stream;
use ratatui::backend::Backend;
use tokio::sync::mpsc;

use crate::{
    application::{Application, ApplicationError},
    chats::{self, Message, ToolCall},
    interface::{self, Interface},
};

pub enum Event {
    LoginMessage(String),
    LoginSucceeded,
    LoginFailed(String),
    MessageDelta {
        turn: u64,
        content: String,
    },
    ThinkingDelta {
        turn: u64,
        content: String,
    },
    ToolCallReceived {
        turn: u64,
        call: ToolCall,
    },
    ProviderItemsReceived {
        turn: u64,
        items: Vec<serde_json::Value>,
    },
    ResponseEnded {
        turn: u64,
        prompt_tokens: u64,
        completion_tokens: u64,
        cached_tokens: u64,
    },
    ToolCompleted {
        turn: u64,
        call_id: String,
        content: String,
        display: Option<crate::tools::ToolDisplay>,
    },
    RequestFailed {
        turn: u64,
        error: ApplicationError,
    },
}

pub type Events = mpsc::UnboundedReceiver<Event>;
pub(crate) type EventSender = mpsc::UnboundedSender<Event>;

pub(crate) async fn run_single_prompt_loop(
    application: &mut Application,
    background_events: &mut Events,
) -> Result<String, ApplicationError> {
    while application.response_started.is_some() {
        let request = application
            .active_request
            .as_mut()
            .expect("an active response has an active request");
        let request_identifier = request.id();
        if let Err(error) = request.await {
            if error.is_panic() {
                std::panic::resume_unwind(error.into_panic());
            }
            panic!("active request was cancelled unexpectedly: {error}");
        }
        while let Ok(event) = background_events.try_recv() {
            chats::apply_event(application, event);
            if application
                .active_request
                .as_ref()
                .is_none_or(|request| request.id() != request_identifier)
            {
                break;
            }
        }
        if application.response_started.is_some()
            && application
                .active_request
                .as_ref()
                .is_none_or(|request| request.id() == request_identifier)
        {
            panic!("request ended without completing its work");
        }
    }
    if let Some(error) = application.error.take() {
        return Err(error);
    }
    match application.session.messages.last() {
        Some(Message::Model { content, .. }) => Ok(content.clone()),
        _ => panic!("completed conversation has a final model response"),
    }
}

pub(crate) async fn run_interactive_loop<BackendType, EventSource>(
    application: &mut Application,
    interface: &mut Interface<BackendType, EventSource>,
    events: &mut Events,
) -> Result<(), ApplicationError>
where
    BackendType: Backend,
    BackendType::Error: Send + Sync + 'static,
    EventSource: Stream<Item = io::Result<TerminalEvent>> + Unpin,
{
    loop {
        interface::draw(interface, application)?;
        tokio::select! {
            input = interface::wait_for_input(interface) => {
                if interface::handle_input(application, input?).is_break() {
                    return Ok(());
                }
            }
            event = events.recv() => {
                let event = event.expect("the application holds an event sender");
                chats::apply_event(application, event);
            }
            () = tokio::time::sleep(Duration::from_millis(80)), if application.response_started.is_some() || interface::is_selection_dragging(application) => {
                interface::advance_selection_scroll(application);
            }
        }
    }
}

